// Generated by scripts/help-build.ts from content/help: don't edit by hand (run: npx tsx scripts/help-build.ts)
import type { HelpArticle } from "./types";

export const HELP_ARTICLES: Record<string, HelpArticle[]> = {"en":[{"slug":"getting-started","title":"Get your school started","summary":"The five steps from an empty school to its first decided result, and how the checklist on your home page tracks them.","roles":["admin"],"group":"Getting started","features":["career-core","class-assessments"],"checked":"2026-11-11","order":1,"blocks":[{"t":"p","c":[{"t":"text","v":"When you open the career center as a school admin, your home page shows "},{"t":"ui","v":"Get started with Build & Defend"},{"t":"text","v":". It lists five steps, and each one ticks itself when your school has really done it. You don't mark anything by hand."}]},{"t":"ol","items":[[{"t":"ui","v":"Add your faculty"},{"t":"text","v":". Invite your teachers from "},{"t":"ui","v":"People"},{"t":"text","v":". Each teacher gets an e-mail with where to sign in. See "},{"t":"link","v":"Add people to your school","href":"/help/add-people"},{"t":"text","v":"."}],[{"t":"ui","v":"Add a class and its students"},{"t":"text","v":". Teachers create their classes and import the roster from a spreadsheet. See "},{"t":"link","v":"Create a class and import its roster","href":"/help/classes-and-rosters"},{"t":"text","v":"."}],[{"t":"ui","v":"Create an assessment from a template"},{"t":"text","v":". A teacher picks a template, such as an essay or a project defense, and adjusts the rubric and the viva. See "},{"t":"link","v":"Create an assessment","href":"/help/create-an-assessment"},{"t":"text","v":"."}],[{"t":"ui","v":"Give it to a class"},{"t":"text","v":". Students are e-mailed and see it under "},{"t":"ui","v":"My assessments"},{"t":"text","v":". See "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}],[{"t":"ui","v":"Decide the first results"},{"t":"text","v":". Teachers review each student's work and viva, and decide. See "},{"t":"link","v":"Review a student's evidence","href":"/help/review-the-evidence"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Each step has a link that takes you to the page where it's done."}]},{"t":"note","c":[{"t":"text","v":"When all five steps are done, the checklist goes away. If your school is in a pilot, your home page then shows the pilot's dates and a link to its results."}]},{"t":"h2","c":[{"t":"text","v":"Who does what"}]},{"t":"ul","items":[[{"t":"b","v":"School admins"},{"t":"text","v":" invite people, see every class and assessment, and can resolve appeals."}],[{"t":"b","v":"Teachers"},{"t":"text","v":" create classes, assessments and decisions for their own classes."}],[{"t":"b","v":"Students"},{"t":"text","v":" hand in their work and do the viva."}]]}],"text":"When you open the career center as a school admin, your home page shows Get started with Build & Defend. It lists five steps, and each one ticks itself when your school has really done it. You don't mark anything by hand. Add your faculty. Invite your teachers from People. Each teacher gets an e-mail with where to sign in. See Add people to your school.Add a class and its students. Teachers create their classes and import the roster from a spreadsheet. See Create a class and import its roster.Create an assessment from a template. A teacher picks a template, such as an essay or a project defense, and adjusts the rubric and the viva. See Create an assessment.Give it to a class. Students are e-mailed and see it under My assessments. See Give an assessment to a class.Decide the first results. Teachers review each student's work and viva, and decide. See Review a student's evidence. Each step has a link that takes you to the page where it's done. When all five steps are done, the checklist goes away. If your school is in a pilot, your home page then shows the pilot's dates and a link to its results. Who does what School admins invite people, see every class and assessment, and can resolve appeals.Teachers create classes, assessments and decisions for their own classes.Students hand in their work and do the viva."},{"slug":"help-and-support","title":"Get help and contact support","summary":"Where the help center is, and who to contact when an article doesn't answer your question.","roles":["admin","teacher","staff","student"],"group":"Getting started","features":["help-center"],"checked":"2026-11-11","order":2,"blocks":[{"t":"p","c":[{"t":"text","v":"Open the help center from the question-mark button at the top of any page. Search for what you're trying to do, or browse the guides for your role. Each article shows when it was last checked against the app."}]},{"t":"h2","c":[{"t":"text","v":"Still need help?"}]},{"t":"p","c":[{"t":"text","v":"At the end of every help page is "},{"t":"ui","v":"Still need help?"},{"t":"text","v":":"}]},{"t":"ul","items":[[{"t":"b","v":"School admins, teachers and career staff"},{"t":"text","v":" can write to Edulexa support. Say "},{"t":"ui","v":"What it's about"},{"t":"text","v":" and "},{"t":"ui","v":"What happened, and what you expected"},{"t":"text","v":", then "},{"t":"ui","v":"Send to support"},{"t":"text","v":". We see the page you came from, and we reply within two working days, by e-mail."}],[{"t":"b","v":"Students"},{"t":"text","v":" get help from their own school first. The help center shows your school's contact, or ask your teacher or career center."}]]},{"t":"h2","c":[{"t":"text","v":"Tell us what's missing"}]},{"t":"p","c":[{"t":"text","v":"Each article asks "},{"t":"ui","v":"Was this helpful?"},{"t":"text","v":". Your answer is counted without your name or school, and so are searches that find nothing, so we know which guides to improve or write next."}]}],"text":"Open the help center from the question-mark button at the top of any page. Search for what you're trying to do, or browse the guides for your role. Each article shows when it was last checked against the app. Still need help? At the end of every help page is Still need help?: School admins, teachers and career staff can write to Edulexa support. Say What it's about and What happened, and what you expected, then Send to support. We see the page you came from, and we reply within two working days, by e-mail.Students get help from their own school first. The help center shows your school's contact, or ask your teacher or career center. Tell us what's missing Each article asks Was this helpful?. Your answer is counted without your name or school, and so are searches that find nothing, so we know which guides to improve or write next."},{"slug":"add-people","title":"Add people to your school","summary":"Invite teachers and career staff one by one, or import a student roster from a spreadsheet.","roles":["admin"],"group":"People and classes","features":["career-core"],"checked":"2026-11-11","order":10,"blocks":[{"t":"p","c":[{"t":"text","v":"Everyone at your school is on the "},{"t":"ui","v":"People"},{"t":"text","v":" page of the career center. You can search by name or e-mail, filter by role, change someone's role, or remove them."}]},{"t":"h2","c":[{"t":"text","v":"Invite one person"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"People"},{"t":"text","v":" and find "},{"t":"ui","v":"Invite someone"},{"t":"text","v":"."}],[{"t":"text","v":"Enter their e-mail address and name."}],[{"t":"text","v":"Choose their role:"}]]},{"t":"ul","items":[[{"t":"ui","v":"Faculty"},{"t":"text","v":": teachers. They create classes and assessments and decide results."}],[{"t":"ui","v":"Counselor"},{"t":"text","v":": career staff who work with students."}],[{"t":"ui","v":"Career center admin"},{"t":"text","v":": school admins. They can do everything, including inviting people."}],[{"t":"ui","v":"Employer relations"},{"t":"text","v":": staff who work with employers."}],[{"t":"ui","v":"Student"}]]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Send invite"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Teachers and staff get an e-mail with where to sign in. Students added here aren't e-mailed: they hear about each assessment when a teacher gives it to their class."}]},{"t":"h2","c":[{"t":"text","v":"Import students from a spreadsheet"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Import student roster"},{"t":"text","v":", choose a CSV file."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Preview"},{"t":"text","v":". You see who would be added or updated, and any rows with problems."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Confirm import"},{"t":"text","v":". Rows with problems are skipped."}]]},{"t":"note","c":[{"t":"text","v":"Teachers usually import their own class lists instead, from the class page. See "},{"t":"link","v":"Create a class and import its roster","href":"/help/classes-and-rosters"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"People sign in with the e-mail address you entered. When they sign in for the first time, their account is linked to your school."}]}],"text":"Everyone at your school is on the People page of the career center. You can search by name or e-mail, filter by role, change someone's role, or remove them. Invite one person Open People and find Invite someone.Enter their e-mail address and name.Choose their role: Faculty: teachers. They create classes and assessments and decide results.Counselor: career staff who work with students.Career center admin: school admins. They can do everything, including inviting people.Employer relations: staff who work with employers.Student Select Send invite. Teachers and staff get an e-mail with where to sign in. Students added here aren't e-mailed: they hear about each assessment when a teacher gives it to their class. Import students from a spreadsheet Under Import student roster, choose a CSV file.Select Preview. You see who would be added or updated, and any rows with problems.Select Confirm import. Rows with problems are skipped. Teachers usually import their own class lists instead, from the class page. See Create a class and import its roster. People sign in with the e-mail address you entered. When they sign in for the first time, their account is linked to your school."},{"slug":"classes-and-rosters","title":"Create a class and import its roster","summary":"Make a class, bring in its students from a spreadsheet, and add a co-teacher.","roles":["teacher","admin"],"group":"People and classes","features":["class-assessments"],"checked":"2026-11-11","order":11,"blocks":[{"t":"h2","c":[{"t":"text","v":"Create a class"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Classes"},{"t":"text","v":" and find "},{"t":"ui","v":"New class"},{"t":"text","v":"."}],[{"t":"text","v":"Enter the "},{"t":"ui","v":"Class name"},{"t":"text","v":", for example \"CS 341, Fall 2026\". The program and graduation year are optional."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Create class"},{"t":"text","v":". You're the class's owner."}]]},{"t":"h2","c":[{"t":"text","v":"Import the roster"}]},{"t":"p","c":[{"t":"text","v":"On the class page, use "},{"t":"ui","v":"Import roster"},{"t":"text","v":". Either choose a "},{"t":"ui","v":"CSV file"},{"t":"text","v":" or use "},{"t":"ui","v":"Or paste the rows"},{"t":"text","v":", then select "},{"t":"ui","v":"Import"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"The file needs a header row with these columns:"}]},{"t":"ul","items":[[{"t":"code","v":"name"},{"t":"text","v":" and "},{"t":"code","v":"email"},{"t":"text","v":" (required)"}],[{"t":"code","v":"roll_number"},{"t":"text","v":" and "},{"t":"code","v":"branch"},{"t":"text","v":" (optional)"}]]},{"t":"p","c":[{"t":"text","v":"For example:"}]},{"t":"p","c":[{"t":"code","v":"name,email,roll_number"}]},{"t":"p","c":[{"t":"code","v":"Priya Raman,priya@college.edu,CS-101"}]},{"t":"p","c":[{"t":"text","v":"If any row has a problem, nothing is imported and each problem is listed with its row number, so you can fix the file and import again. Files can be up to 5 MB."}]},{"t":"p","c":[{"t":"text","v":"Students sign in with the e-mail address on the roster. The class shows who has signed in."}]},{"t":"h2","c":[{"t":"text","v":"Add a co-teacher"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Add a co-teacher"},{"t":"text","v":", pick a teacher at your school who has already signed in, and select "},{"t":"ui","v":"Add teacher"},{"t":"text","v":". Co-teachers see the class's students and work, and can review and decide."}]},{"t":"note","c":[{"t":"text","v":"To give the class an assessment, use "},{"t":"ui","v":"Give this class an assessment"},{"t":"text","v":" on the class page. See "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}]}],"text":"Create a class Open Classes and find New class.Enter the Class name, for example \"CS 341, Fall 2026\". The program and graduation year are optional.Select Create class. You're the class's owner. Import the roster On the class page, use Import roster. Either choose a CSV file or use Or paste the rows, then select Import. The file needs a header row with these columns: name and email (required)roll_number and branch (optional) For example: name,email,roll_number Priya Raman,priya@college.edu,CS-101 If any row has a problem, nothing is imported and each problem is listed with its row number, so you can fix the file and import again. Files can be up to 5 MB. Students sign in with the e-mail address on the roster. The class shows who has signed in. Add a co-teacher Under Add a co-teacher, pick a teacher at your school who has already signed in, and select Add teacher. Co-teachers see the class's students and work, and can review and decide. To give the class an assessment, use Give this class an assessment on the class page. See Give an assessment to a class."},{"slug":"create-an-assessment","title":"Create an assessment","summary":"Pick a template for the kind of work, write the instructions, and publish it.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":20,"blocks":[{"t":"p","c":[{"t":"text","v":"Every assessment works the same way: students hand in their own work, then explain and defend it in a viva, and you decide the result. The template sets what students hand in and gives you a starting rubric."}]},{"t":"h2","c":[{"t":"text","v":"Choose a template"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Assessments"},{"t":"text","v":". Under "},{"t":"ui","v":"New assessment"},{"t":"text","v":", choose one:"}]},{"t":"p","c":[{"t":"b","v":"Any subject"}]},{"t":"ul","items":[[{"t":"ui","v":"Essay"},{"t":"text","v":", "},{"t":"ui","v":"Report"},{"t":"text","v":", "},{"t":"ui","v":"Lab report"},{"t":"text","v":" or "},{"t":"ui","v":"Presentation"},{"t":"text","v":": students hand in a PDF, Word or PowerPoint file, or paste their text. The viva asks about what's in it."}]]},{"t":"p","c":[{"t":"b","v":"Code and exams"}]},{"t":"ul","items":[[{"t":"ui","v":"Project defense"},{"t":"text","v":": students hand in their own GitHub repository or a .zip of their project."}],[{"t":"ui","v":"Coding task"},{"t":"text","v":": students solve a coding task in the browser workspace."}],[{"t":"ui","v":"Written exam plus viva"},{"t":"text","v":": students take a written exam, then explain their answers."}]]},{"t":"p","c":[{"t":"text","v":"Give it a "},{"t":"ui","v":"Title"},{"t":"text","v":" and select "},{"t":"ui","v":"Continue"},{"t":"text","v":". For a coding task or an exam, you then choose which task or exam it uses."}]},{"t":"h2","c":[{"t":"text","v":"Fill in the details"}]},{"t":"ul","items":[[{"t":"ui","v":"Instructions for students"},{"t":"text","v":": what to hand in, what the viva covers, and anything they should prepare."}],[{"t":"text","v":"The "},{"t":"ui","v":"Rubric"},{"t":"text","v":" and the "},{"t":"ui","v":"Viva"},{"t":"text","v":": see "},{"t":"link","v":"Set the rubric and the viva","href":"/help/rubric-and-viva"},{"t":"text","v":"."}],[{"t":"ui","v":"Issue a credential when a student passes"},{"t":"text","v":": on by default; turn it off for practice or homework."}]]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Save changes"},{"t":"text","v":" as you go. When it's ready, select "},{"t":"ui","v":"Publish"},{"t":"text","v":". Then give it to a class: see "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Once students have started, the task, the rubric and the viva are locked, so everyone is assessed the same way. You can still change the title, the instructions and the credential setting. To change more, copy it into a new assessment."}]},{"t":"p","c":[{"t":"text","v":"You can "},{"t":"ui","v":"Archive"},{"t":"text","v":" an assessment you no longer use, and "},{"t":"ui","v":"Restore"},{"t":"text","v":" it later."}]}],"text":"Every assessment works the same way: students hand in their own work, then explain and defend it in a viva, and you decide the result. The template sets what students hand in and gives you a starting rubric. Choose a template Open Assessments. Under New assessment, choose one: Any subject Essay, Report, Lab report or Presentation: students hand in a PDF, Word or PowerPoint file, or paste their text. The viva asks about what's in it. Code and exams Project defense: students hand in their own GitHub repository or a .zip of their project.Coding task: students solve a coding task in the browser workspace.Written exam plus viva: students take a written exam, then explain their answers. Give it a Title and select Continue. For a coding task or an exam, you then choose which task or exam it uses. Fill in the details Instructions for students: what to hand in, what the viva covers, and anything they should prepare.The Rubric and the Viva: see Set the rubric and the viva.Issue a credential when a student passes: on by default; turn it off for practice or homework. Select Save changes as you go. When it's ready, select Publish. Then give it to a class: see Give an assessment to a class. Once students have started, the task, the rubric and the viva are locked, so everyone is assessed the same way. You can still change the title, the instructions and the credential setting. To change more, copy it into a new assessment. You can Archive an assessment you no longer use, and Restore it later."},{"slug":"rubric-and-viva","title":"Set the rubric and the viva","summary":"Decide what a good answer shows, how much each part counts, and how the viva runs.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":21,"blocks":[{"t":"h2","c":[{"t":"text","v":"The rubric"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Rubric"},{"t":"text","v":" is the list of what you'll score, each from 0 to 100. Each template starts with its own criteria; an essay, for example, starts with the argument, the evidence and sources, understanding their own essay, handling other views, and explaining clearly."}]},{"t":"ul","items":[[{"t":"text","v":"Change any criterion's name, what a strong answer shows, and its weight."}],[{"t":"text","v":"Use "},{"t":"ui","v":"Add a criterion"},{"t":"text","v":" for more (between 2 and 8 criteria)."}],[{"t":"text","v":"The weights must add up to 100. The builder shows the running total."}]]},{"t":"p","c":[{"t":"text","v":"When you decide, you score each criterion, and the weighted score out of 100 is worked out for you."}]},{"t":"h2","c":[{"t":"text","v":"The viva"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Viva"},{"t":"text","v":" is a short oral examination about the student's own work. An AI examiner asks the questions, one at a time, each about what the student handed in. It never gives hints, answers or scores."}]},{"t":"ul","items":[[{"t":"ui","v":"How students answer"},{"t":"text","v":": "},{"t":"ui","v":"By voice"},{"t":"text","v":", "},{"t":"ui","v":"In writing"},{"t":"text","v":", or "},{"t":"ui","v":"The student chooses"},{"t":"text","v":"."}],[{"t":"ui","v":"Questions"},{"t":"text","v":": between 3 and 10."}],[{"t":"ui","v":"Minutes"},{"t":"text","v":": about how long a voice viva lasts, between 5 and 30."}],[{"t":"ui","v":"Language"},{"t":"text","v":": the viva's language, or "},{"t":"ui","v":"Each student's own choice"},{"t":"text","v":" from their settings."}]]},{"t":"p","c":[{"t":"text","v":"Students are judged on understanding, never on accent, grammar or spelling."}]},{"t":"note","c":[{"t":"text","v":"Voice vivas use your school's AI voice minutes. When there are none left, or voice doesn't work for a student, they answer in writing instead, and you see that it was written. See "},{"t":"link","v":"AI voice minutes and billing","href":"/help/billing-and-voice-minutes"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"A change task (code only)"}]},{"t":"p","c":[{"t":"text","v":"Project and coding assessments can also ask for one small change to the student's own code before the viva. See "},{"t":"link","v":"Add a change task","href":"/help/change-task"},{"t":"text","v":"."}]}],"text":"The rubric The Rubric is the list of what you'll score, each from 0 to 100. Each template starts with its own criteria; an essay, for example, starts with the argument, the evidence and sources, understanding their own essay, handling other views, and explaining clearly. Change any criterion's name, what a strong answer shows, and its weight.Use Add a criterion for more (between 2 and 8 criteria).The weights must add up to 100. The builder shows the running total. When you decide, you score each criterion, and the weighted score out of 100 is worked out for you. The viva The Viva is a short oral examination about the student's own work. An AI examiner asks the questions, one at a time, each about what the student handed in. It never gives hints, answers or scores. How students answer: By voice, In writing, or The student chooses.Questions: between 3 and 10.Minutes: about how long a voice viva lasts, between 5 and 30.Language: the viva's language, or Each student's own choice from their settings. Students are judged on understanding, never on accent, grammar or spelling. Voice vivas use your school's AI voice minutes. When there are none left, or voice doesn't work for a student, they answer in writing instead, and you see that it was written. See AI voice minutes and billing. A change task (code only) Project and coding assessments can also ask for one small change to the student's own code before the viva. See Add a change task."},{"slug":"change-task","title":"Add a change task","summary":"Before the viva, ask for one small, timed change to the student's own code, checked by tests.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":22,"blocks":[{"t":"p","c":[{"t":"text","v":"A change task shows whether students can work with their own code: someone who didn't write it usually can't change it quickly. It's available for "},{"t":"ui","v":"Project defense"},{"t":"text","v":" and "},{"t":"ui","v":"Coding task"},{"t":"text","v":" assessments."}]},{"t":"h2","c":[{"t":"text","v":"Turn it on"}]},{"t":"p","c":[{"t":"text","v":"In the assessment's "},{"t":"ui","v":"Change task"},{"t":"text","v":" section, tick "},{"t":"ui","v":"Ask for a small change to their own code"},{"t":"text","v":" and set the "},{"t":"ui","v":"Minutes for the change"},{"t":"text","v":" (between 10 and 60)."}]},{"t":"p","c":[{"t":"text","v":"Turning it on adds a criterion for the change (15%) to the rubric and scales the others down to fit. You can edit it like any other criterion."}]},{"t":"h2","c":[{"t":"text","v":"What students get"}]},{"t":"p","c":[{"t":"text","v":"After a student hands in their work, the AI writes a short change request for their code and checks that it can be done. When it's ready, the student starts it; the clock runs from then. They work in the coding workspace on a copy of their own code, with the AI assistant off, and hand in their change. Hidden tests check it."}]},{"t":"h2","c":[{"t":"text","v":"What you see"}]},{"t":"p","c":[{"t":"text","v":"On the student's evidence page you see the request, how long they took, which tests passed, and exactly what they changed. If their change touched the tests themselves, you're told the results can't be trusted."}]},{"t":"note","c":[{"t":"text","v":"If the student's language isn't supported, or the change can't be prepared, the change task is skipped and the student goes straight to the viva; its criterion then doesn't count for them."}]}],"text":"A change task shows whether students can work with their own code: someone who didn't write it usually can't change it quickly. It's available for Project defense and Coding task assessments. Turn it on In the assessment's Change task section, tick Ask for a small change to their own code and set the Minutes for the change (between 10 and 60). Turning it on adds a criterion for the change (15%) to the rubric and scales the others down to fit. You can edit it like any other criterion. What students get After a student hands in their work, the AI writes a short change request for their code and checks that it can be done. When it's ready, the student starts it; the clock runs from then. They work in the coding workspace on a copy of their own code, with the AI assistant off, and hand in their change. Hidden tests check it. What you see On the student's evidence page you see the request, how long they took, which tests passed, and exactly what they changed. If their change touched the tests themselves, you're told the results can't be trusted. If the student's language isn't supported, or the change can't be prepared, the change task is skipped and the student goes straight to the viva; its criterion then doesn't count for them."},{"slug":"give-to-a-class","title":"Give an assessment to a class","summary":"Set when it opens and when it's due; students are e-mailed and see it in their list.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":23,"blocks":[{"t":"p","c":[{"t":"text","v":"An assessment must be published before you can give it to a class. See "},{"t":"link","v":"Create an assessment","href":"/help/create-an-assessment"},{"t":"text","v":"."}]},{"t":"ol","items":[[{"t":"text","v":"On the assessment, find "},{"t":"ui","v":"Give it to"},{"t":"text","v":" and "},{"t":"ui","v":"Choose a class"},{"t":"text","v":"."}],[{"t":"text","v":"Leave "},{"t":"ui","v":"Opens (optional)"},{"t":"text","v":" empty to open it now, or pick a date and time."}],[{"t":"text","v":"Set when it's "},{"t":"ui","v":"Due"},{"t":"text","v":"."}],[{"t":"text","v":"Decide whether to "},{"t":"ui","v":"Accept late work (marked late)"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Give to class"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Students are e-mailed when you give it to the class, and reminded before the due date. They find it under "},{"t":"ui","v":"My assessments"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"You can give the same assessment to several classes, each with its own dates. Each class then has its own page of students and their work."}]},{"t":"h2","c":[{"t":"text","v":"Following the class"}]},{"t":"p","c":[{"t":"text","v":"The class's page shows every student and where they are: "},{"t":"ui","v":"Not started"},{"t":"text","v":", "},{"t":"ui","v":"Working on it"},{"t":"text","v":", "},{"t":"ui","v":"Viva next"},{"t":"text","v":", "},{"t":"ui","v":"Ready for review"},{"t":"text","v":" and "},{"t":"ui","v":"Decided"},{"t":"text","v":". Open a student's evidence from there, or use the "},{"t":"ui","v":"Review"},{"t":"text","v":" page for everything waiting across your classes."}]},{"t":"note","c":[{"t":"text","v":"To withdraw it from a class before anyone has started, use "},{"t":"ui","v":"Take back"},{"t":"text","v":"."}]}],"text":"An assessment must be published before you can give it to a class. See Create an assessment. On the assessment, find Give it to and Choose a class.Leave Opens (optional) empty to open it now, or pick a date and time.Set when it's Due.Decide whether to Accept late work (marked late).Select Give to class. Students are e-mailed when you give it to the class, and reminded before the due date. They find it under My assessments. You can give the same assessment to several classes, each with its own dates. Each class then has its own page of students and their work. Following the class The class's page shows every student and where they are: Not started, Working on it, Viva next, Ready for review and Decided. Open a student's evidence from there, or use the Review page for everything waiting across your classes. To withdraw it from a class before anyone has started, use Take back."},{"slug":"review-the-evidence","title":"Review a student's evidence","summary":"Read the work, the viva and the AI's suggested scores, and look at the points worth asking about.","roles":["teacher","admin"],"group":"Reviewing and deciding","features":["class-assessments"],"checked":"2026-11-11","order":30,"blocks":[{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Review"},{"t":"text","v":" to see every attempt waiting for your decision across your classes, oldest first. Select "},{"t":"ui","v":"Open"},{"t":"text","v":" to see a student's evidence."}]},{"t":"h2","c":[{"t":"text","v":"What the evidence page shows"}]},{"t":"ul","items":[[{"t":"b","v":"The work."},{"t":"text","v":" Whatever the student handed in: the text of their document by page or slide (with "},{"t":"ui","v":"Download the original"},{"t":"text","v":"), their repository or project files, their coding task with its tests, or their exam answers."}],[{"t":"b","v":"The change task"},{"t":"text","v":", if the assessment has one."}],[{"t":"b","v":"The viva."},{"t":"text","v":" Every question and answer, whether it was by voice or in writing, and how long it took."}],[{"t":"text","v":"The "},{"t":"ui","v":"Suggested scores"},{"t":"text","v":": the AI's suggestion for each criterion, with a short reason and, where it can, a quote from the student's own answers or work. It's only a suggestion: students never see it, and you decide."}],[{"t":"text","v":"The "},{"t":"ui","v":"Points to talk about"},{"t":"text","v":": patterns worth asking the student about, for example work much like another student's, answers read out from the document, or a viva answered in writing after voice failed. They're not findings, and nothing here decides anything."}]]},{"t":"note","c":[{"t":"text","v":"Each time you open a student's evidence, it's recorded, as it is for any student record."}]},{"t":"p","c":[{"t":"text","v":"When you're ready, decide on the same page. See "},{"t":"link","v":"Decide and handle appeals","href":"/help/decide-and-appeals"},{"t":"text","v":"."}]}],"text":"Open Review to see every attempt waiting for your decision across your classes, oldest first. Select Open to see a student's evidence. What the evidence page shows The work. Whatever the student handed in: the text of their document by page or slide (with Download the original), their repository or project files, their coding task with its tests, or their exam answers.The change task, if the assessment has one.The viva. Every question and answer, whether it was by voice or in writing, and how long it took.The Suggested scores: the AI's suggestion for each criterion, with a short reason and, where it can, a quote from the student's own answers or work. It's only a suggestion: students never see it, and you decide.The Points to talk about: patterns worth asking the student about, for example work much like another student's, answers read out from the document, or a viva answered in writing after voice failed. They're not findings, and nothing here decides anything. Each time you open a student's evidence, it's recorded, as it is for any student record. When you're ready, decide on the same page. See Decide and handle appeals."},{"slug":"decide-and-appeals","title":"Decide and handle appeals","summary":"Score each criterion, choose pass, resubmit or fail, and answer a student's appeal.","roles":["teacher","admin"],"group":"Reviewing and deciding","features":["class-assessments"],"checked":"2026-11-11","order":31,"blocks":[{"t":"h2","c":[{"t":"text","v":"Decide"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Your decision"},{"t":"text","v":" on the student's evidence page:"}]},{"t":"ol","items":[[{"t":"text","v":"Score each criterion with a whole number from 0 to 100. Each starts from the AI's suggestion when there is one; change any you disagree with. The weighted score is worked out for you."}],[{"t":"text","v":"Choose "},{"t":"ui","v":"Pass"},{"t":"text","v":", "},{"t":"ui","v":"Resubmit"},{"t":"text","v":" or "},{"t":"ui","v":"Fail"},{"t":"text","v":"."}],[{"t":"text","v":"Write a "},{"t":"ui","v":"Comment for the student"},{"t":"text","v":". It's needed to ask for a resubmission or to fail, so the student knows why."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save decision"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The student sees your decision, your scores and your comment. They never see the AI's suggestions."}]},{"t":"ul","items":[[{"t":"b","v":"Pass:"},{"t":"text","v":" if the assessment issues credentials, a signed credential is added to the student's wallet. Anyone can verify it."}],[{"t":"b","v":"Resubmit:"},{"t":"text","v":" the student can hand in again, even after the due date. Their next attempt starts fresh, with your feedback shown to them."}],[{"t":"b","v":"Fail:"},{"t":"text","v":" the student is told they didn't pass, and that they can appeal."}]]},{"t":"note","c":[{"t":"text","v":"If the student's work or viva changes after you decide, the evidence page says so."}]},{"t":"h2","c":[{"t":"text","v":"Appeals"}]},{"t":"p","c":[{"t":"text","v":"A student can appeal a decision once, within 14 days. Appeals appear under "},{"t":"ui","v":"Appeals"},{"t":"text","v":" on the "},{"t":"ui","v":"Review"},{"t":"text","v":" page. You can't answer an appeal of your own decision: another teacher of the class, or a school admin, does."}]},{"t":"p","c":[{"t":"text","v":"Open the appeal, read the student's reason, and write a "},{"t":"ui","v":"Response to the student"},{"t":"text","v":". Then either "},{"t":"ui","v":"Keep the decision"},{"t":"text","v":" or "},{"t":"ui","v":"Change it"},{"t":"text","v":" and "},{"t":"ui","v":"Save the new decision"},{"t":"text","v":". The student sees your response."}]}],"text":"Decide Under Your decision on the student's evidence page: Score each criterion with a whole number from 0 to 100. Each starts from the AI's suggestion when there is one; change any you disagree with. The weighted score is worked out for you.Choose Pass, Resubmit or Fail.Write a Comment for the student. It's needed to ask for a resubmission or to fail, so the student knows why.Select Save decision. The student sees your decision, your scores and your comment. They never see the AI's suggestions. Pass: if the assessment issues credentials, a signed credential is added to the student's wallet. Anyone can verify it.Resubmit: the student can hand in again, even after the due date. Their next attempt starts fresh, with your feedback shown to them.Fail: the student is told they didn't pass, and that they can appeal. If the student's work or viva changes after you decide, the evidence page says so. Appeals A student can appeal a decision once, within 14 days. Appeals appear under Appeals on the Review page. You can't answer an appeal of your own decision: another teacher of the class, or a school admin, does. Open the appeal, read the student's reason, and write a Response to the student. Then either Keep the decision or Change it and Save the new decision. The student sees your response."},{"slug":"results-credentials-lms","title":"Results, credentials and grades in your LMS","summary":"See a class's results, download them, withdraw a credential, and send grades to Canvas, Moodle or Blackboard.","roles":["teacher","admin"],"group":"Results","features":["class-assessments","credentials","lms-lti"],"checked":"2026-11-11","order":40,"blocks":[{"t":"h2","c":[{"t":"text","v":"A class's results"}]},{"t":"p","c":[{"t":"text","v":"The class's page for an assessment shows its "},{"t":"ui","v":"Results"},{"t":"text","v":" from your decisions: how many passed, were asked to resubmit or didn't pass, the average and middle scores, and the average for each rubric criterion. Use "},{"t":"ui","v":"Download results (CSV)"},{"t":"text","v":" for a spreadsheet of every student."}]},{"t":"h2","c":[{"t":"text","v":"Credentials"}]},{"t":"p","c":[{"t":"text","v":"When a student passes an assessment that issues credentials, a signed credential goes into their wallet, with a public page anyone can use to check it."}]},{"t":"p","c":[{"t":"text","v":"If a credential was issued by mistake, open the student's evidence and use "},{"t":"ui","v":"Withdraw the credential"},{"t":"text","v":", with the reason. Its page then shows it's no longer valid."}]},{"t":"h2","c":[{"t":"text","v":"Grades in your LMS"}]},{"t":"p","c":[{"t":"text","v":"If your school uses Canvas, Moodle or Blackboard, Edulexa can send each decision's score to the course gradebook (LTI 1.3). Your school sets up the connection once with Edulexa's team. Then:"}]},{"t":"ol","items":[[{"t":"text","v":"In your course, add the Edulexa activity and pick this assessment."}],[{"t":"text","v":"Each student opens it once from the course, so the gradebook knows who they are."}],[{"t":"text","v":"Every decision sends the score to the gradebook."}]]},{"t":"p","c":[{"t":"text","v":"The class's page shows each student's grade: sent, waiting to send, not sent, or not linked yet (the student hasn't opened it from the course). If one wasn't sent, select "},{"t":"ui","v":"Send again"},{"t":"text","v":"."}]}],"text":"A class's results The class's page for an assessment shows its Results from your decisions: how many passed, were asked to resubmit or didn't pass, the average and middle scores, and the average for each rubric criterion. Use Download results (CSV) for a spreadsheet of every student. Credentials When a student passes an assessment that issues credentials, a signed credential goes into their wallet, with a public page anyone can use to check it. If a credential was issued by mistake, open the student's evidence and use Withdraw the credential, with the reason. Its page then shows it's no longer valid. Grades in your LMS If your school uses Canvas, Moodle or Blackboard, Edulexa can send each decision's score to the course gradebook (LTI 1.3). Your school sets up the connection once with Edulexa's team. Then: In your course, add the Edulexa activity and pick this assessment.Each student opens it once from the course, so the gradebook knows who they are.Every decision sends the score to the gradebook. The class's page shows each student's grade: sent, waiting to send, not sent, or not linked yet (the student hasn't opened it from the course). If one wasn't sent, select Send again."},{"slug":"pilot-results","title":"Read your assessment results","summary":"Completion, review time, how often the AI's suggestions matched your teachers, points raised, appeals and students' answers.","roles":["admin","teacher"],"group":"Results","features":["class-assessments"],"checked":"2026-11-11","order":41,"blocks":[{"t":"p","c":[{"t":"text","v":"The results page brings together every assessment in a period. Teachers find it under "},{"t":"ui","v":"Results"},{"t":"text","v":" and see their own classes. School admins find it under "},{"t":"ui","v":"Assessment results"},{"t":"text","v":" and see the whole school."}]},{"t":"p","c":[{"t":"text","v":"If your school is in a pilot, the page covers the pilot's dates; otherwise choose the dates you want."}]},{"t":"h2","c":[{"t":"text","v":"What it shows"}]},{"t":"ul","items":[[{"t":"b","v":"Completion:"},{"t":"text","v":" how many students were in the classes, started, handed in, finished the viva, and have a decision."}],[{"t":"b","v":"Review time:"},{"t":"text","v":" how long teachers spent actively on each student's evidence before deciding. Only time with the page open, in front and in use is counted."}],[{"t":"b","v":"The AI and your teachers:"},{"t":"text","v":" how often the AI's suggested scores were within 5 points of the teacher's final score, how often they were left unchanged, and the average difference."}],[{"t":"b","v":"Points to talk about:"},{"t":"text","v":" how often the evidence raised each kind of point."}],[{"t":"b","v":"Appeals:"},{"t":"text","v":" how many are open, upheld or changed."}],[{"t":"b","v":"Students' answers:"},{"t":"text","v":" after the viva, students can answer two questions (was it fair, and did the viva reflect their own work) and leave a comment. Answers are anonymous: they're kept without the student or the attempt, and shown only once there are at least 3."}]]},{"t":"p","c":[{"t":"text","v":"Each assessment has its own figures below the totals, and the whole page can be downloaded as a CSV for a review meeting."}]}],"text":"The results page brings together every assessment in a period. Teachers find it under Results and see their own classes. School admins find it under Assessment results and see the whole school. If your school is in a pilot, the page covers the pilot's dates; otherwise choose the dates you want. What it shows Completion: how many students were in the classes, started, handed in, finished the viva, and have a decision.Review time: how long teachers spent actively on each student's evidence before deciding. Only time with the page open, in front and in use is counted.The AI and your teachers: how often the AI's suggested scores were within 5 points of the teacher's final score, how often they were left unchanged, and the average difference.Points to talk about: how often the evidence raised each kind of point.Appeals: how many are open, upheld or changed.Students' answers: after the viva, students can answer two questions (was it fair, and did the viva reflect their own work) and leave a comment. Answers are anonymous: they're kept without the student or the attempt, and shown only once there are at least 3. Each assessment has its own figures below the totals, and the whole page can be downloaded as a CSV for a review meeting."},{"slug":"billing-and-voice-minutes","title":"AI voice minutes and billing","summary":"Your plan, its monthly AI voice minutes, buying more in packs of 100, and changing or cancelling the plan.","roles":["admin"],"group":"Billing","features":["school-plans"],"checked":"2026-11-11","order":50,"blocks":[{"t":"p","c":[{"t":"text","v":"Schools that signed up online manage their plan on the "},{"t":"ui","v":"Billing"},{"t":"text","v":" page. If Edulexa's team set your school up on a contract, Billing says so instead: contact us about invoices or changes."}]},{"t":"h2","c":[{"t":"text","v":"AI voice minutes"}]},{"t":"p","c":[{"t":"text","v":"Voice vivas use AI voice minutes. Your plan includes a number each month, and Billing shows how many you've used. When none are left, students answer the viva in writing instead; nothing else stops."}]},{"t":"p","c":[{"t":"text","v":"If you need more, use "},{"t":"ui","v":"Buy 100 minutes"},{"t":"text","v":". You pay once: by card, or in India by card or UPI. Bought minutes:"}]},{"t":"ul","items":[[{"t":"text","v":"are added as soon as the payment is confirmed;"}],[{"t":"text","v":"are used after your plan's monthly minutes;"}],[{"t":"text","v":"are kept from month to month until your plan ends."}]]},{"t":"h2","c":[{"t":"text","v":"Change or cancel your plan"}]},{"t":"ul","items":[[{"t":"ui","v":"Change plan"},{"t":"text","v":" to move between plans, paid monthly or yearly ("},{"t":"ui","v":"Yearly: 2 months free"},{"t":"text","v":")."}],[{"t":"ui","v":"Card and invoices"},{"t":"text","v":" (card payments) opens the page for your card and invoices."}],[{"t":"ui","v":"Cancel plan"},{"t":"text","v":": your school stays open until the end of the trial or the period you've paid for, then becomes read-only. Bought voice minutes end with the plan."}]]},{"t":"note","c":[{"t":"text","v":"A read-only school can still sign in, see and export everything until its data is deleted. Choose a plan and "},{"t":"ui","v":"Pay and reopen"},{"t":"text","v":" to carry on."}]}],"text":"Schools that signed up online manage their plan on the Billing page. If Edulexa's team set your school up on a contract, Billing says so instead: contact us about invoices or changes. AI voice minutes Voice vivas use AI voice minutes. Your plan includes a number each month, and Billing shows how many you've used. When none are left, students answer the viva in writing instead; nothing else stops. If you need more, use Buy 100 minutes. You pay once: by card, or in India by card or UPI. Bought minutes: are added as soon as the payment is confirmed;are used after your plan's monthly minutes;are kept from month to month until your plan ends. Change or cancel your plan Change plan to move between plans, paid monthly or yearly (Yearly: 2 months free).Card and invoices (card payments) opens the page for your card and invoices.Cancel plan: your school stays open until the end of the trial or the period you've paid for, then becomes read-only. Bought voice minutes end with the plan. A read-only school can still sign in, see and export everything until its data is deleted. Choose a plan and Pay and reopen to carry on."},{"slug":"privacy-requests","title":"Answer students' privacy requests","summary":"Handle a student's request for a copy of their data, a correction or deletion, within your school's deadline.","roles":["admin","staff"],"group":"Your data and privacy","features":["career-privacy"],"checked":"2026-11-11","order":60,"blocks":[{"t":"p","c":[{"t":"text","v":"Students ask for a copy of their data, a correction or deletion from their privacy page. A request also arrives when a student deletes their Edulexa account: it lists the records your school holds about them, such as class attempts, documents and roster entries."}]},{"t":"p","c":[{"t":"text","v":"Requests are on the career center's privacy page, under "},{"t":"ui","v":"Privacy requests"},{"t":"text","v":" and "},{"t":"ui","v":"Request queue"},{"t":"text","v":". Each shows when it's due; overdue ones are marked. Your school sets how many days you have under "},{"t":"ui","v":"Days to answer requests"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Handle a request"}]},{"t":"p","c":[{"t":"text","v":"Open the request and select "},{"t":"ui","v":"Start"},{"t":"text","v":". Then:"}]},{"t":"ul","items":[[{"t":"b","v":"A copy of their data:"},{"t":"text","v":" use "},{"t":"ui","v":"Preview export"},{"t":"text","v":" to check it, then "},{"t":"ui","v":"Release export to the student"},{"t":"text","v":". They download it from their privacy page."}],[{"t":"b","v":"A correction:"},{"t":"text","v":" make the change, then "},{"t":"ui","v":"Mark corrected"},{"t":"text","v":" with a "},{"t":"ui","v":"Note to the student"},{"t":"text","v":"."}],[{"t":"b","v":"Deletion:"},{"t":"text","v":" use "},{"t":"ui","v":"Show erasure plan"},{"t":"text","v":" to see exactly what would be deleted, table by table. To go ahead, "},{"t":"ui","v":"Type ERASE to confirm"},{"t":"text","v":" and select "},{"t":"ui","v":"Erase and complete"},{"t":"text","v":". Erasure can't be undone. Records the law requires your school to keep are kept, as the plan shows."}]]},{"t":"p","c":[{"t":"text","v":"To refuse a request, use "},{"t":"ui","v":"Decline"},{"t":"text","v":" with a note explaining why. Every step is kept in the request's audit trail."}]}],"text":"Students ask for a copy of their data, a correction or deletion from their privacy page. A request also arrives when a student deletes their Edulexa account: it lists the records your school holds about them, such as class attempts, documents and roster entries. Requests are on the career center's privacy page, under Privacy requests and Request queue. Each shows when it's due; overdue ones are marked. Your school sets how many days you have under Days to answer requests. Handle a request Open the request and select Start. Then: A copy of their data: use Preview export to check it, then Release export to the student. They download it from their privacy page.A correction: make the change, then Mark corrected with a Note to the student.Deletion: use Show erasure plan to see exactly what would be deleted, table by table. To go ahead, Type ERASE to confirm and select Erase and complete. Erasure can't be undone. Records the law requires your school to keep are kept, as the plan shows. To refuse a request, use Decline with a note explaining why. Every step is kept in the request's audit trail."},{"slug":"your-data","title":"Your data and privacy","summary":"See and control how your school uses your data, ask for a copy, a correction or deletion, and delete your account.","roles":["student"],"group":"Your data and privacy","features":["career-privacy","member-privacy"],"checked":"2026-11-11","order":61,"blocks":[{"t":"h2","c":[{"t":"text","v":"At your school"}]},{"t":"p","c":[{"t":"text","v":"Your school's privacy page is in the career center under your account: "},{"t":"link","v":"Privacy","href":"/student/privacy"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"b","v":"How your data is used:"},{"t":"text","v":" uses that need your consent are listed, each with an on/off switch. Withdrawing stops the use from then on."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Your data rights"},{"t":"text","v":", at "},{"t":"ui","v":"What do you want?"},{"t":"text","v":" choose a copy of your data, a correction, or deletion, add any details, and select "},{"t":"ui","v":"Send request"},{"t":"text","v":". Your school's career office answers within the time shown."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Your data requests"},{"t":"text","v":", follow your requests, and "},{"t":"ui","v":"Download"},{"t":"text","v":" your copy when it's ready."}]]},{"t":"p","c":[{"t":"text","v":"If you're under the age your country sets, a parent or guardian may need to agree first."}]},{"t":"h2","c":[{"t":"text","v":"Your Edulexa account"}]},{"t":"p","c":[{"t":"text","v":"To download everything in your account, or delete it, go to "},{"t":"link","v":"Privacy and your data","href":"/settings/privacy"},{"t":"text","v":". Deleting your account removes your own activity. Records your school holds about your class work, such as your attempts and documents, are the school's: your deletion sends the school a request to erase them, and the school completes it."}]}],"text":"At your school Your school's privacy page is in the career center under your account: Privacy. How your data is used: uses that need your consent are listed, each with an on/off switch. Withdrawing stops the use from then on.Under Your data rights, at What do you want? choose a copy of your data, a correction, or deletion, add any details, and select Send request. Your school's career office answers within the time shown.Under Your data requests, follow your requests, and Download your copy when it's ready. If you're under the age your country sets, a parent or guardian may need to agree first. Your Edulexa account To download everything in your account, or delete it, go to Privacy and your data. Deleting your account removes your own activity. Records your school holds about your class work, such as your attempts and documents, are the school's: your deletion sends the school a request to erase them, and the school completes it."},{"slug":"hand-in-your-work","title":"Hand in your work","summary":"Start the assessment and hand in a document, a GitHub repository, a project, a coding task or an exam.","roles":["student"],"group":"Handing in","features":["class-assessments"],"checked":"2026-11-11","order":70,"blocks":[{"t":"p","c":[{"t":"text","v":"Your assessments are under "},{"t":"ui","v":"My assessments"},{"t":"text","v":". Open one to see what to do, how you're assessed, and when it's due. When you're ready, select "},{"t":"ui","v":"Start"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"How you hand in depends on the assessment:"}]},{"t":"h2","c":[{"t":"text","v":"An essay, report, lab report or presentation"}]},{"t":"p","c":[{"t":"text","v":"Choose your file (PDF, Word or PowerPoint, up to 25 MB) and select "},{"t":"ui","v":"Upload and hand in"},{"t":"text","v":". Or use "},{"t":"ui","v":"Paste the text instead"},{"t":"text","v":" and "},{"t":"ui","v":"Hand in this text"},{"t":"text","v":" (50 words at least)."}]},{"t":"p","c":[{"t":"text","v":"The viva's questions are about what's in your file, so it needs readable text. A scan or a photo of your pages can't be read: save your work as a PDF with text, upload the Word or PowerPoint file, or paste the text. Old formats such as .doc and .ppt need saving as .docx, .pptx or PDF first."}]},{"t":"h2","c":[{"t":"text","v":"A project"}]},{"t":"ul","items":[[{"t":"text","v":"A GitHub repository, under "},{"t":"ui","v":"Hand in a GitHub repository"},{"t":"text","v":": enter "},{"t":"ui","v":"Your GitHub username"},{"t":"text","v":" and the "},{"t":"ui","v":"Repository"},{"t":"text","v":", then select "},{"t":"ui","v":"Check the repository"},{"t":"text","v":". To show it's yours, add the code you're given to your GitHub profile bio (or a public gist's description), then select "},{"t":"ui","v":"I've added it, check now"},{"t":"text","v":". You can remove the code afterwards."}],[{"t":"text","v":"A .zip, under "},{"t":"ui","v":"Or upload your project"},{"t":"text","v":": your project folder zipped, up to 25 MB, without dependencies or build output such as node_modules."}]]},{"t":"h2","c":[{"t":"text","v":"A coding task or an exam"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Open the coding task"},{"t":"text","v":" or "},{"t":"ui","v":"Open the exam"},{"t":"text","v":", do it there, then come back and select "},{"t":"ui","v":"Hand in my solution"},{"t":"text","v":" or "},{"t":"ui","v":"Hand in my exam"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"You can replace what you handed in until your viva starts. From then on, your work is fixed, because the questions are about it."}]},{"t":"p","c":[{"t":"text","v":"Next comes the viva (and, for some coding assessments, a short change task first). See "},{"t":"link","v":"Do the viva","href":"/help/the-viva"},{"t":"text","v":"."}]}],"text":"Your assessments are under My assessments. Open one to see what to do, how you're assessed, and when it's due. When you're ready, select Start. How you hand in depends on the assessment: An essay, report, lab report or presentation Choose your file (PDF, Word or PowerPoint, up to 25 MB) and select Upload and hand in. Or use Paste the text instead and Hand in this text (50 words at least). The viva's questions are about what's in your file, so it needs readable text. A scan or a photo of your pages can't be read: save your work as a PDF with text, upload the Word or PowerPoint file, or paste the text. Old formats such as .doc and .ppt need saving as .docx, .pptx or PDF first. A project A GitHub repository, under Hand in a GitHub repository: enter Your GitHub username and the Repository, then select Check the repository. To show it's yours, add the code you're given to your GitHub profile bio (or a public gist's description), then select I've added it, check now. You can remove the code afterwards.A .zip, under Or upload your project: your project folder zipped, up to 25 MB, without dependencies or build output such as node_modules. A coding task or an exam Select Open the coding task or Open the exam, do it there, then come back and select Hand in my solution or Hand in my exam. You can replace what you handed in until your viva starts. From then on, your work is fixed, because the questions are about it. Next comes the viva (and, for some coding assessments, a short change task first). See Do the viva."},{"slug":"change-task-student","title":"Do the change task","summary":"For some coding assessments, you make one small, timed change to your own code before the viva.","roles":["student"],"group":"Handing in","features":["class-assessments"],"checked":"2026-11-11","order":71,"blocks":[{"t":"p","c":[{"t":"text","v":"Some coding assessments ask you to make one small change to your own code before the viva. It shows you know your code well enough to change it."}]},{"t":"ol","items":[[{"t":"text","v":"After you hand in your work, the change task is prepared from your own code. This usually takes a minute or two; the page updates by itself."}],[{"t":"text","v":"When it's ready, the page shows how many minutes you'll have. You see what to change only when you start, and the clock runs from then. Select "},{"t":"ui","v":"Start the change task (20 minutes)"},{"t":"text","v":" (your time may differ)."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Open the workspace (new tab)"},{"t":"text","v":". You work on a copy of your code, with the AI assistant off."}],[{"t":"text","v":"Make the change, run the tests, and submit in the workspace. Then come back and select "},{"t":"ui","v":"Hand in the change"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"If time runs out before you hand in, whatever you submitted last in the workspace counts. Then the viva comes next: see "},{"t":"link","v":"Do the viva","href":"/help/the-viva"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Once your change task has started, the work you handed in can't be replaced."}]}],"text":"Some coding assessments ask you to make one small change to your own code before the viva. It shows you know your code well enough to change it. After you hand in your work, the change task is prepared from your own code. This usually takes a minute or two; the page updates by itself.When it's ready, the page shows how many minutes you'll have. You see what to change only when you start, and the clock runs from then. Select Start the change task (20 minutes) (your time may differ).Select Open the workspace (new tab). You work on a copy of your code, with the AI assistant off.Make the change, run the tests, and submit in the workspace. Then come back and select Hand in the change. If time runs out before you hand in, whatever you submitted last in the workspace counts. Then the viva comes next: see Do the viva. Once your change task has started, the work you handed in can't be replaced."},{"slug":"the-viva","title":"Do the viva","summary":"Explain your own work by voice or in writing. What to expect, and what to do if voice doesn't work.","roles":["student"],"group":"The viva","features":["class-assessments"],"checked":"2026-11-11","order":72,"blocks":[{"t":"p","c":[{"t":"text","v":"The viva is a short oral examination about the work you handed in. An AI examiner asks a few questions, one at a time: why you made a choice, what a part of your work means, or how you'd answer an objection. It doesn't give hints or scores. Your teacher reads the whole viva and decides your result."}]},{"t":"h2","c":[{"t":"text","v":"By voice"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Start the viva by voice"},{"t":"text","v":" and allow your browser to use the microphone. Answer each question out loud; you see what's said as you go. When you've answered the last question, select "},{"t":"ui","v":"End the viva and hand in"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Find a quiet place, and give yourself the time the assessment page shows."}]},{"t":"h2","c":[{"t":"text","v":"In writing"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Answer in writing"},{"t":"text","v":", or it's offered automatically when the viva is in writing. Type each answer and select "},{"t":"ui","v":"Send answer"},{"t":"text","v":"; the last one is "},{"t":"ui","v":"Send my last answer and hand in"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Tips"}]},{"t":"ul","items":[[{"t":"text","v":"Explain in your own words. Spelling, grammar and accent don't count; understanding does."}],[{"t":"text","v":"Talk about your own work, in detail. It's fine to say what you'd do differently."}],[{"t":"text","v":"Don't read your work out. Your teacher can see when answers are mostly copied from it."}]]},{"t":"h2","c":[{"t":"text","v":"If voice doesn't work"}]},{"t":"p","c":[{"t":"text","v":"If the call doesn't connect, or nothing you said was kept, use "},{"t":"ui","v":"Voice didn't work? Answer in writing"},{"t":"text","v":". Your teacher sees that you answered in writing after voice failed, so it doesn't count against you."}]},{"t":"p","c":[{"t":"text","v":"After the viva, you may be asked "},{"t":"ui","v":"Two quick questions"},{"t":"text","v":" about the assessment. Your answers are anonymous. Then your teacher decides: see "},{"t":"link","v":"Your result and appeals","href":"/help/results-and-appeals"},{"t":"text","v":"."}]}],"text":"The viva is a short oral examination about the work you handed in. An AI examiner asks a few questions, one at a time: why you made a choice, what a part of your work means, or how you'd answer an objection. It doesn't give hints or scores. Your teacher reads the whole viva and decides your result. By voice Select Start the viva by voice and allow your browser to use the microphone. Answer each question out loud; you see what's said as you go. When you've answered the last question, select End the viva and hand in. Find a quiet place, and give yourself the time the assessment page shows. In writing Select Answer in writing, or it's offered automatically when the viva is in writing. Type each answer and select Send answer; the last one is Send my last answer and hand in. Tips Explain in your own words. Spelling, grammar and accent don't count; understanding does.Talk about your own work, in detail. It's fine to say what you'd do differently.Don't read your work out. Your teacher can see when answers are mostly copied from it. If voice doesn't work If the call doesn't connect, or nothing you said was kept, use Voice didn't work? Answer in writing. Your teacher sees that you answered in writing after voice failed, so it doesn't count against you. After the viva, you may be asked Two quick questions about the assessment. Your answers are anonymous. Then your teacher decides: see Your result and appeals."},{"slug":"results-and-appeals","title":"Your result and appeals","summary":"See your teacher's decision and comment, find your credential, appeal once, or hand in again.","roles":["student"],"group":"After the decision","features":["class-assessments","credentials"],"checked":"2026-11-11","order":80,"blocks":[{"t":"p","c":[{"t":"text","v":"When your teacher has decided, the assessment page under "},{"t":"ui","v":"My assessments"},{"t":"text","v":" shows your result: your score for each part of the rubric, your overall score out of 100, and your teacher's comment."}]},{"t":"h2","c":[{"t":"text","v":"If you passed"}]},{"t":"p","c":[{"t":"text","v":"If the assessment issues credentials, a signed credential is added to your wallet. Select "},{"t":"ui","v":"View your credential"},{"t":"text","v":" to see it, or open "},{"t":"ui","v":"Your wallet"},{"t":"text","v":" for all of them. Each has a public page you can share; anyone can check it's real."}]},{"t":"h2","c":[{"t":"text","v":"If you're asked to resubmit"}]},{"t":"p","c":[{"t":"text","v":"You can hand in again, even after the due date. Select "},{"t":"ui","v":"Start attempt 2"},{"t":"text","v":" (or the next number). Your teacher's feedback on the attempt before stays on the page while you work."}]},{"t":"h2","c":[{"t":"text","v":"If you think the decision is wrong"}]},{"t":"p","c":[{"t":"text","v":"You can appeal once, within 14 days. Select "},{"t":"ui","v":"Appeal"},{"t":"text","v":", explain why the decision should change, and select "},{"t":"ui","v":"Send appeal"},{"t":"text","v":". Another teacher of your class, or a school admin, looks at it and answers on the same page. They either keep the decision or change it."}]},{"t":"note","c":[{"t":"text","v":"Once you start a new attempt, you can no longer appeal the decision on the one before."}]}],"text":"When your teacher has decided, the assessment page under My assessments shows your result: your score for each part of the rubric, your overall score out of 100, and your teacher's comment. If you passed If the assessment issues credentials, a signed credential is added to your wallet. Select View your credential to see it, or open Your wallet for all of them. Each has a public page you can share; anyone can check it's real. If you're asked to resubmit You can hand in again, even after the due date. Select Start attempt 2 (or the next number). Your teacher's feedback on the attempt before stays on the page while you work. If you think the decision is wrong You can appeal once, within 14 days. Select Appeal, explain why the decision should change, and select Send appeal. Another teacher of your class, or a school admin, looks at it and answers on the same page. They either keep the decision or change it. Once you start a new attempt, you can no longer appeal the decision on the one before."}],"es":[],"hi":[],"ar":[]};
